static void prReject(const std::string& source, unsigned line, ds_preview::ErrorCode code) {
 ds_preview::Program p;check(!p.compile(source.c_str(),source.size()),"retained source rejects before publication");
 check(p.error().line==line&&p.error().code==code,"exact physical REPEAT diagnostic");
 lower::reset();rejected(source.c_str());check(operations().empty(),"invalid retained source emits no mock application reports");
 std::cout<<"DIAGNOSTIC line="<<p.error().line<<" code="<<unsigned(p.error().code)<<" message="<<ds_preview::message(p.error().code)<<"\n";
}
static void prTaps(unsigned count,uint8_t usage,uint8_t mods=0){check(operations().size()==2*count,"exact tap count");for(unsigned i=0;i<count;++i){exactReport(i*2,mods,{usage});exactReport(i*2+1,0,{});}}
static void prCancelled(){trialDone();check(route_u::status().reason==route_u::Reason::Cancelled&&!route_u::owned()&&!hid_backend::hasPersistent(),"STOP completed cleanup and detached lease");noReplay();}
static std::string prText(const NumericHarness& h){std::string s;for(auto e:h.events){if(e.type==ds_preview::EventType::Character)s+=char(e.value);else if(e.type==ds_preview::EventType::KeyTap&&e.value==40)s+='\n';}return s;}

